/* Desk Pet — Pallarium module.
   A sprite creature that lives on your screen: walks, idles, blinks, flips,
   follows your cursor when it's near, and can be grabbed and tossed with real
   physics (gravity, bounce, spin, squash-and-stretch). Toggle from the header
   paw button. Fully torn down on disable. */
(function () {
  var MOD = "desk-pet";
  var controller = null; // active pet controller instance
  var species = "cat";   // "cat" | "dog" | "dino" — swapped from the right-click menu
  var SPECIES_CRY = { cat: "MEOW!", dog: "WOOF!", dino: "RAWR!" };
  var PET_TYPES = [
    { id: "tabby", name: "Orange Tabby", filter: "" },
    { id: "blue",  name: "Blue Tabby",   filter: "hue-rotate(190deg) saturate(1.3) brightness(1.02)" },
    { id: "pink",  name: "Pink Tabby",   filter: "hue-rotate(275deg) saturate(1.35) brightness(1.05)" },
    { id: "mint",  name: "Mint Tabby",   filter: "hue-rotate(105deg) saturate(1.15) brightness(1.03)" },
    { id: "grey",  name: "Grey Tabby",   filter: "grayscale(0.85) brightness(0.92)" },
  ];

  /* ---- real 2D sprite sheets (CC0 "Cat & Dog" by pzUH / gameart2d.com, OpenGameArt)
     cute grey tabby, tight-cropped horizontal strips, cat faces RIGHT.
     idle:10@64x96  walk:10@64x96  run:8@68x96  jump:8@78x96 */
  var idleImg = new Image(); idleImg.src = "data:image/png;base64,";
  var walkImg = new Image(); walkImg.src = "data:image/png;base64,";
  var runImg  = new Image(); runImg.src  = "data:image/png;base64,";
  var jumpImg = new Image(); jumpImg.src = "data:image/png;base64,";

  /* cat sheets shared with the battle arena */
  window.__deskPetCat = {
    idle: { img: idleImg, fw: 64, fh: 96, n: 10 },
    walk: { img: walkImg, fw: 64, fh: 96, n: 10 },
    run:  { img: runImg,  fw: 68, fh: 96, n: 8 },
    jump: { img: jumpImg, fw: 78, fh: 96, n: 8 },
  };

  /* palette for the little orange cat-blob */
  var C = {
    body: "#f6a04d", bodyLo: "#e0842f", belly: "#ffe0b8",
    ear: "#f6a04d", earIn: "#ff9db1", eye: "#241708", shine: "#ffffff",
    blush: "#ff8f9c", nose: "#c65b3e", stripe: "#d97a26",
  };

  /* ------------------------------------------------------------------ *
   *  SPRITE — draws the creature facing RIGHT, centred at (cx,cy).
   *  p = { legPhase, breathe, ears, eye, mouth, tailPhase, airborne }
   * ------------------------------------------------------------------ */
  function drawCreature(ctx, cx, cy, p) {
    var br = p.breathe || 0;
    var bodyW = 34, bodyH = 30 - br * 2;

    // tail
    var tp = p.tailPhase;
    ctx.save();
    ctx.strokeStyle = C.bodyLo; ctx.lineWidth = 7; ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(cx - bodyW * 0.7, cy + 4);
    ctx.quadraticCurveTo(
      cx - bodyW - 10, cy + 2 + Math.sin(tp) * 6,
      cx - bodyW - 6 + Math.cos(tp) * 4, cy - 14 + Math.sin(tp) * 8);
    ctx.stroke();
    ctx.restore();

    // legs (4) — walk cycle or splay when airborne
    var legY = cy + bodyH - 2;
    var spread = p.airborne;
    var legs = [-16, -6, 6, 16];
    for (var i = 0; i < 4; i++) {
      var phase = p.legPhase + (i % 2) * Math.PI;
      var lift = spread > 0.02 ? 0 : Math.max(0, Math.sin(phase)) * 5;
      var sx = legs[i] + spread * (legs[i] > 0 ? 10 : -10);
      ctx.fillStyle = C.bodyLo;
      roundRect(ctx, cx + sx - 4, legY - lift, 8, 12 + spread * 4, 4);
      ctx.fill();
    }

    // body
    ctx.fillStyle = C.body;
    ellipse(ctx, cx, cy, bodyW, bodyH); ctx.fill();
    // back stripe
    ctx.save();
    ctx.beginPath(); ellipse(ctx, cx, cy, bodyW, bodyH); ctx.clip();
    ctx.strokeStyle = C.stripe; ctx.lineWidth = 4;
    for (var s = -2; s <= 2; s++) {
      ctx.beginPath();
      ctx.moveTo(cx + s * 11 - 4, cy - bodyH);
      ctx.lineTo(cx + s * 11 + 4, cy - bodyH + 12);
      ctx.stroke();
    }
    ctx.restore();
    // belly
    ctx.fillStyle = C.belly;
    ellipse(ctx, cx + 6, cy + 6, bodyW * 0.55, bodyH * 0.6); ctx.fill();

    // ears
    var perk = p.ears; // 0..1
    drawEar(ctx, cx - 14, cy - bodyH + 4, -1, perk);
    drawEar(ctx, cx + 14, cy - bodyH + 4, 1, perk);

    // face
    var fx = cx + 8, fy = cy - 2;
    drawEyes(ctx, fx, fy, p.eye);
    // nose + mouth
    ctx.fillStyle = C.nose;
    ctx.beginPath(); ctx.moveTo(fx + 12, fy + 4);
    ctx.lineTo(fx + 16, fy + 4); ctx.lineTo(fx + 14, fy + 7); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = C.nose; ctx.lineWidth = 1.6; ctx.lineCap = "round";
    ctx.beginPath();
    if (p.mouth === "happy") {
      ctx.moveTo(fx + 10, fy + 8); ctx.quadraticCurveTo(fx + 14, fy + 13, fx + 18, fy + 8);
    } else {
      ctx.moveTo(fx + 14, fy + 7); ctx.lineTo(fx + 14, fy + 9);
      ctx.moveTo(fx + 14, fy + 9); ctx.quadraticCurveTo(fx + 11, fy + 11, fx + 9, fy + 9);
      ctx.moveTo(fx + 14, fy + 9); ctx.quadraticCurveTo(fx + 17, fy + 11, fx + 19, fy + 9);
    }
    ctx.stroke();
    // blush when happy
    if (p.mouth === "happy") {
      ctx.fillStyle = "rgba(255,143,156,0.6)";
      ellipse(ctx, fx - 2, fy + 7, 4, 3); ctx.fill();
      ellipse(ctx, fx + 22, fy + 7, 4, 3); ctx.fill();
    }
  }

  function drawEar(ctx, x, y, dir, perk) {
    var tilt = (1 - perk) * 8 * dir;
    ctx.save();
    ctx.fillStyle = C.ear;
    ctx.beginPath();
    ctx.moveTo(x - 8, y + 6);
    ctx.lineTo(x + tilt, y - 14 - perk * 4);
    ctx.lineTo(x + 8, y + 6);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = C.earIn;
    ctx.beginPath();
    ctx.moveTo(x - 4, y + 3);
    ctx.lineTo(x + tilt * 0.7, y - 9 - perk * 3);
    ctx.lineTo(x + 4, y + 3);
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  function drawEyes(ctx, fx, fy, state) {
    var L = fx + 2, R = fx + 16, ey = fy;
    ctx.fillStyle = C.eye;
    if (state === "blink") {
      ctx.strokeStyle = C.eye; ctx.lineWidth = 2; ctx.lineCap = "round";
      ctx.beginPath(); ctx.moveTo(L - 3, ey); ctx.lineTo(L + 3, ey);
      ctx.moveTo(R - 3, ey); ctx.lineTo(R + 3, ey); ctx.stroke();
      return;
    }
    if (state === "happy") {
      ctx.strokeStyle = C.eye; ctx.lineWidth = 2.4; ctx.lineCap = "round"; ctx.fillStyle = "none";
      ctx.beginPath(); arcUp(ctx, L, ey); arcUp(ctx, R, ey); ctx.stroke();
      return;
    }
    if (state === "dizzy") {
      ctx.strokeStyle = C.eye; ctx.lineWidth = 1.6;
      spiral(ctx, L, ey); spiral(ctx, R, ey);
      return;
    }
    // open / scared
    var big = state === "scared" ? 4.6 : 3.6;
    eyeball(ctx, L, ey, big); eyeball(ctx, R, ey, big);
  }
  function eyeball(ctx, x, y, r) {
    ctx.fillStyle = C.eye; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
    ctx.fillStyle = C.shine; ctx.beginPath(); ctx.arc(x - r * 0.35, y - r * 0.4, r * 0.35, 0, 6.283); ctx.fill();
  }
  function arcUp(ctx, x, y) { ctx.moveTo(x - 4, y + 1); ctx.quadraticCurveTo(x, y - 4, x + 4, y + 1); }
  function spiral(ctx, x, y) {
    ctx.beginPath();
    for (var a = 0; a < 12; a += 0.4) {
      var rr = a * 0.35, px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
      a === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    }
    ctx.stroke();
  }
  function ellipse(ctx, x, y, rx, ry) { ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, 6.283); }
  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  /* ---- comic-strip / emote overlays (drawn on the pet canvas) ---- */
  function drawStar(ctx, x, y, outer, spikes, inner) {
    ctx.beginPath();
    for (var i = 0; i < spikes * 2; i++) {
      var r = i % 2 ? inner : outer;
      var a = i / (spikes * 2) * Math.PI * 2 - Math.PI / 2;
      var px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }
  function drawFightCloud(ctx, cx, cy, t, word) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(Math.sin(t * 2.5) * 0.1);
    var pts = 14, base = 33;
    ctx.beginPath();
    for (var i = 0; i <= pts; i++) {
      var a = i / pts * Math.PI * 2;
      var rr = base + Math.sin(a * 3 + t * 4) * 7 + Math.cos(a * 5 - t * 3) * 4;
      var px = Math.cos(a) * rr, py = Math.sin(a) * rr;
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = "rgba(246,246,250,0.96)"; ctx.fill();
    ctx.lineWidth = 2.5; ctx.strokeStyle = "rgba(110,110,132,0.95)"; ctx.stroke();
    ctx.strokeStyle = "rgba(150,150,172,0.7)"; ctx.lineWidth = 1.5;
    for (var k = 0; k < 3; k++) {
      var off = t * 5 + k * 2.1;
      ctx.beginPath(); ctx.arc(Math.cos(off) * 7, Math.sin(off) * 7, 9 + k * 4, off, off + 2.2); ctx.stroke();
    }
    ctx.fillStyle = "#666";
    for (var l = 0; l < 5; l++) {
      var la = l / 5 * Math.PI * 2 + t * 3;
      var lr = base + 3 + Math.sin(t * 8 + l) * 3;
      ctx.beginPath(); ctx.arc(Math.cos(la) * lr, Math.sin(la) * lr, 3.5, 0, 6.283); ctx.fill();
    }
    ctx.restore();
    ctx.save(); ctx.translate(cx, cy);
    ctx.fillStyle = "#ffd54a"; ctx.strokeStyle = "#e0a000"; ctx.lineWidth = 1;
    for (var s = 0; s < 3; s++) {
      var sa = t * 3.2 + s * 2.1;
      drawStar(ctx, Math.cos(sa) * 42, Math.sin(sa) * 30 - 6, 5, 5, 2.4);
    }
    ctx.restore();
    ctx.save(); ctx.translate(cx, cy - 2);
    ctx.rotate(-0.14 + Math.sin(t * 6) * 0.05);
    var fs = Math.round(19 + Math.sin(t * 12) * 2);
    ctx.font = "900 " + fs + "px Impact, Haettenschweiler, system-ui, sans-serif";
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.lineWidth = 4.5; ctx.strokeStyle = "#1a1a1a"; ctx.strokeText(word, 0, 0);
    ctx.fillStyle = "#ffe23d"; ctx.fillText(word, 0, 0);
    ctx.restore();
  }
  function drawZzz(ctx, x, y, t) {
    ctx.save();
    ctx.fillStyle = "#4a90d9"; ctx.strokeStyle = "rgba(255,255,255,0.9)"; ctx.lineWidth = 2;
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    for (var i = 0; i < 3; i++) {
      var ph = (t * 0.6 + i * 0.6) % 1.8;
      var sz = 9 + i * 4, yy = y - ph * 14 - i * 4, xx = x + ph * 6 + i * 3;
      ctx.globalAlpha = Math.max(0, 1 - ph / 1.8);
      ctx.font = "700 " + sz + "px system-ui, sans-serif";
      ctx.strokeText("Z", xx, yy); ctx.fillText("Z", xx, yy);
    }
    ctx.restore();
  }
  function drawHeart(ctx, x, y, t) {
    var s = 7 * (0.9 + Math.sin(t * 4) * 0.12), yy = y - Math.sin(t * 1.5) * 3;
    ctx.save(); ctx.translate(x, yy); ctx.scale(s / 7, s / 7);
    ctx.beginPath();
    ctx.moveTo(0, 3);
    ctx.bezierCurveTo(-5, -3, -9, 3, 0, 9);
    ctx.bezierCurveTo(9, 3, 5, -3, 0, 3);
    ctx.closePath();
    ctx.fillStyle = "#ff5a7a"; ctx.fill();
    ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,255,0.9)"; ctx.stroke();
    ctx.restore();
  }
  function drawBang(ctx, x, y) {
    ctx.save(); ctx.translate(x, y);
    ctx.beginPath(); ctx.arc(0, 0, 9, 0, 6.283);
    ctx.fillStyle = "#ffd23d"; ctx.fill();
    ctx.lineWidth = 2; ctx.strokeStyle = "#1a1a1a"; ctx.stroke();
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(-1.5, -5, 3, 6);
    ctx.beginPath(); ctx.arc(0, 4, 1.6, 0, 6.283); ctx.fill();
    ctx.restore();
  }
  // trailing dust puffs behind a zooming pet (drawn behind, toward the tail side)
  function drawZoom(ctx, x, y, t, dir) {
    ctx.save();
    ctx.strokeStyle = "rgba(160,160,180,0.85)"; ctx.lineWidth = 3; ctx.lineCap = "round";
    for (var i = 0; i < 3; i++) {
      var off = i * 12 + 6;
      var yy = y + (i - 1) * 7;
      ctx.beginPath();
      ctx.moveTo(x + dir * off, yy);
      ctx.lineTo(x + dir * (off + 16 + Math.sin(t * 20 + i) * 4), yy);
      ctx.stroke();
    }
    ctx.fillStyle = "rgba(200,200,215,0.7)";
    for (var k = 0; k < 4; k++) {
      var a = t * 9 + k * 1.7;
      ctx.beginPath();
      ctx.arc(x + dir * (10 + (k % 2) * 8), y + Math.sin(a) * 8 + 4, 3 + (k % 2), 0, 6.283);
      ctx.fill();
    }
    ctx.restore();
  }

  /* ------------------------------------------------------------------ *
   *  PET CONTROLLER — physics, AI, input.
   * ------------------------------------------------------------------ */
  function makePet(opts) {
    opts = opts || {};
    var mySpecies = SPECIES_CRY[opts.species] ? opts.species : species;
    // cats are the quick ones, dogs the baseline, dinos lumber
    var SPECIES_SPEED = { cat: 1.4, dog: 1.0, dino: 0.85 };
    function speciesSpeed() { return SPECIES_SPEED[mySpecies] || 1; }
    var SIZE = 120, HALF = SIZE / 2, FEET = 34;
    var dpr = Math.min(window.devicePixelRatio || 1, 2);

    var el = document.createElement("canvas");
    el.width = SIZE * dpr; el.height = SIZE * dpr;
    el.style.cssText =
      "position:fixed;left:0;top:0;width:" + SIZE + "px;height:" + SIZE + "px;" +
      "z-index:2147483000;cursor:grab;will-change:transform;touch-action:none;";
    var ctx = el.getContext("2d"); ctx.scale(dpr, dpr);

    var shadow = document.createElement("div");
    shadow.style.cssText =
      "position:fixed;left:0;top:0;width:70px;height:16px;z-index:2147482999;pointer-events:none;" +
      "border-radius:50%;background:radial-gradient(ellipse,rgba(0,0,0,.28),transparent 70%);will-change:transform,opacity;";

    document.body.appendChild(shadow);
    document.body.appendChild(el);

    var floorY = function () { return window.innerHeight - FEET; };
    var p = {
      x: Math.min(window.innerWidth * 0.4, 400), y: floorY(),
      vx: 0, vy: 0, rot: 0, angVel: 0,
      dir: 1, legPhase: 0, tailPhase: 0, blinkT: 2 + Math.random() * 3, blinking: 0,
      sx: 1, sy: 1, // squash
      mode: "ground", // ground | air | drag | perch
      targetX: 0, thinkT: 0, action: null, actionT: 0,
      eye: "open", mouth: "neutral", ears: 1,
      emote: null, emoteT: 0,   // "fight" | "sleep" | "love" | "bang"
      fightWord: "POW!",
      pounceT: 0,               // cooldown between pounces at the cursor
      perchTop: 0, perchL: 0, perchR: 0, // ground element the pet is standing on
      restT: 0,                 // time spent idle -> triggers a nap
      zoomLeft: 0,              // remaining dashes in a zoomies fit
      trick: null, trickT: 0,   // commanded trick from the right-click menu
      eatT: 0,                  // munching timer when standing over food
      say: null, sayT: 0,       // speech bubble text
    };
    p.speedMul = 1; p.spinV = 0; p.rotHold = 0;
    p.act = null; p.lastAct = null;
    var world = window.__deskPetWorld || null;
    var scrappy = true;   // false = never swipes at the cursor
    function pick(a) { return a[(Math.random() * a.length) | 0]; }
    var brain = window.__deskPetBrain || null;
    var brainCtx = {
      p: p,
      say: function (t) { say(t); },
      startHop: function (x) { startHop(x); },
      startFlip: function () { startFlip(); },
      species: function () { return mySpecies; },
    };
    if (brain) brain.register(brainCtx);

    var item = null;            // active toy / food on the floor
    var itemDrag = { on: false, samples: [] };
    var mouse = { x: -9999, y: -9999, has: false, moved: 0 };
    var drag = { on: false, ox: 0, oy: 0, samples: [] };
    var FIGHT_WORDS = ["POW!", "BAM!", "WHAP!", "BONK!", "ZAP!", "BIFF!"];

    /* ---- find a real page element to stand on near an x just below the pet ---- */
    function findPerch(atX, fromY) {
      var xs = [atX, atX - 30, atX + 30];
      var best = null;
      for (var i = 0; i < xs.length; i++) {
        var cx = Math.max(2, Math.min(window.innerWidth - 2, xs[i]));
        var stack = document.elementsFromPoint(cx, Math.min(window.innerHeight - 2, fromY + 4));
        for (var j = 0; j < stack.length; j++) {
          var elm = stack[j];
          if (elm === el || elm === shadow) continue;
          if (elm === document.body || elm === document.documentElement) continue;
          var r = elm.getBoundingClientRect();
          if (r.width < 40 || r.height < 8) continue;
          if (r.top < 40 || r.top > window.innerHeight - 20) continue;
          if (r.top >= fromY - 6) continue;          // must be a ledge ABOVE the feet
          if (best === null || r.top < best.top) best = { top: r.top, left: r.left, right: r.right };
        }
      }
      return best;
    }

    /* ---- find the user's chat box or the session list to go sit on ---- */
    function findFavoriteSpot() {
      var sels = [
        'textarea', '[contenteditable="true"]',
        '[class*="composer"]', '[class*="chat-input"]', '[class*="prompt"]',
        '[class*="input-area"]', '[class*="messagebar"]', '[class*="inputWrap"]',
        '[class*="session"]', '[class*="sidebar"]', '[class*="conversation"]',
        'nav', 'aside',
      ];
      var cands = [];
      for (var i = 0; i < sels.length; i++) {
        var list = document.querySelectorAll(sels[i]);
        for (var j = 0; j < list.length && j < 8; j++) {
          var elm = list[j];
          if (elm === el || elm === shadow) continue;
          var r = elm.getBoundingClientRect();
          if (r.width < 90 || r.height < 24) continue;
          if (r.top < 30 || r.top > window.innerHeight - 24) continue;
          var vis = window.getComputedStyle(elm);
          if (vis.visibility === "hidden" || vis.display === "none" || +vis.opacity === 0) continue;
          // prefer a wide, reachable ledge; chat boxes (textarea/composer) score highest
          var priority = i < 8 ? 2 : 1;
          cands.push({ top: r.top, left: r.left, right: r.right, score: priority * 1000 - Math.abs(r.top - p.y) * 0.1 });
        }
      }
      if (!cands.length) return null;
      cands.sort(function (a, b) { return b.score - a.score; });
      return cands[0];
    }

    /* ---- input ---- */
    function onMove(e) {
      mouse.x = e.clientX; mouse.y = e.clientY; mouse.has = true; mouse.moved = performance.now();
      if (drag.on) {
        p.x = e.clientX - drag.ox; p.y = e.clientY - drag.oy;
        var now = performance.now();
        drag.samples.push({ t: now, x: p.x, y: p.y });
        while (drag.samples.length > 6) drag.samples.shift();
      }
    }
    function onDown(e) {
      drag.on = true;
      el.style.cursor = "grabbing";
      drag.ox = e.clientX - p.x; drag.oy = e.clientY - p.y;
      drag.samples = [{ t: performance.now(), x: p.x, y: p.y }];
      p.mode = "drag"; p.vx = p.vy = 0; p.angVel = 0;
      p.eye = "happy"; p.mouth = "happy"; p.ears = 1;
      e.preventDefault();
    }
    function onUp() {
      if (!drag.on) return;
      drag.on = false;
      el.style.cursor = "grab";
      // toss velocity from recent samples
      var s = drag.samples, vx = 0, vy = 0;
      if (s.length >= 2) {
        var a = s[0], b = s[s.length - 1], dt = (b.t - a.t) / 1000;
        if (dt > 0) { vx = (b.x - a.x) / dt; vy = (b.y - a.y) / dt; }
      }
      p.vx = Math.max(-1800, Math.min(1800, vx));
      p.vy = Math.max(-1800, Math.min(1800, vy));
      if (Math.abs(vx) + Math.abs(vy) < 90 && brain) { brain.petted(brainCtx); }
      p.mode = "air";
      p.angVel = (p.vx / 260) + (Math.random() - 0.5) * 4;
      p.eye = Math.abs(p.vx) + Math.abs(p.vy) > 700 ? "scared" : "open";
    }
    el.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerup", onUp);

    /* ------------------------------------------------------------------ *
     *  toys + food: a real physical object the pet chases, bats and eats
     * ------------------------------------------------------------------ */
    var TOYS = [
      { id: "yarn",    glyph: "🧶", name: "Ball of Yarn" },
      { id: "ball",    glyph: "🎾", name: "Tennis Ball" },
      { id: "feather", glyph: "🪶", name: "Feather Wand" },
      { id: "mouse",   glyph: "🐁", name: "Toy Mouse" },
      { id: "laser",   glyph: "🔴", name: "Laser Dot" },
    ];
    var FOODS = [
      { id: "fish",  glyph: "🐟", name: "Fish" },
      { id: "treat", glyph: "🍪", name: "Treat" },
      { id: "milk",  glyph: "🥛", name: "Milk" },
      { id: "chick", glyph: "🍗", name: "Chicken" },
    ];
    var TRICK_WORDS = {
      sit:   "good boy!",
      spin:  "wheee!",
      flip:  "nailed it!",
      speak: "MEOW!",
      play:  "...",
      chase: "zoom!",
    };

    var itemEl = document.createElement("div");
    itemEl.style.cssText =
      "position:fixed;left:0;top:0;width:40px;height:40px;line-height:40px;text-align:center;" +
      "font-size:30px;z-index:2147483001;cursor:grab;user-select:none;touch-action:none;display:none;" +
      "filter:drop-shadow(0 3px 5px rgba(0,0,0,.5));will-change:transform;";
    document.body.appendChild(itemEl);

    /** drop a toy/food into the SHARED world — every pet can chase it */
    function spawnItem(def, kind, atX, atY) {
      if (!world) return;
      if (def.id === "laser") { world.laserOn(); say("!!!"); p.eye = "scared"; p.act = null; return; }
      world.spawn(def, kind, atX, atY);
      p.emote = null; p.restT = 0; p.trick = null; p.act = null;
      p.eye = "happy"; p.mouth = "happy";
      say(kind === "food" ? "nom?" : "oooh!");
    }

    function clearItem() {
      if (world) world.clearAll();
    }

    function onItemDown(e) {
      if (!item) return;
      itemDrag.on = true;
      itemDrag.ox = e.clientX - item.x; itemDrag.oy = e.clientY - item.y;
      itemDrag.samples = [{ t: performance.now(), x: item.x, y: item.y }];
      itemEl.style.cursor = "grabbing";
      item.vx = item.vy = 0;
      e.preventDefault(); e.stopPropagation();
    }
    function onItemMove(e) {
      if (!itemDrag.on || !item) return;
      item.x = e.clientX - itemDrag.ox; item.y = e.clientY - itemDrag.oy;
      itemDrag.samples.push({ t: performance.now(), x: item.x, y: item.y });
      while (itemDrag.samples.length > 6) itemDrag.samples.shift();
    }
    function onItemUp() {
      if (!itemDrag.on || !item) return;
      itemDrag.on = false;
      itemEl.style.cursor = "grab";
      var s = itemDrag.samples;
      if (s.length >= 2) {
        var a = s[0], b = s[s.length - 1], dt = (b.t - a.t) / 1000;
        if (dt > 0) {
          item.vx = Math.max(-2200, Math.min(2200, (b.x - a.x) / dt));
          item.vy = Math.max(-2200, Math.min(2200, (b.y - a.y) / dt));
        }
      }
      item.angVel = item.vx / 60;
      item.life = Math.max(item.life, 10);
      p.zoomLeft = 0; p.emote = null;
      say("mine!");
    }
    itemEl.addEventListener("pointerdown", onItemDown);
    window.addEventListener("pointermove", onItemMove, { passive: true });
    window.addEventListener("pointerup", onItemUp);

    /** item gravity, floor bounce, rolling friction, wall bounce */
    function stepItem(dt) {
      if (!item) return;
      var fY = floorY() + 18;
      if (itemDrag.on) { item.rot += dt * 6; return; }
      item.life -= dt;
      if (item.life <= 0) { clearItem(); return; }
      item.vy += 2400 * dt;
      item.x += item.vx * dt; item.y += item.vy * dt;
      item.rot += item.angVel * dt;
      if (item.x < 18) { item.x = 18; item.vx = Math.abs(item.vx) * 0.6; item.angVel *= -0.6; }
      if (item.x > window.innerWidth - 18) { item.x = window.innerWidth - 18; item.vx = -Math.abs(item.vx) * 0.6; item.angVel *= -0.6; }
      if (item.y >= fY) {
        item.y = fY;
        if (item.vy > 120) { item.vy = -item.vy * 0.42; item.vx *= 0.82; }
        else { item.vy = 0; item.vx *= 0.92; item.angVel = item.vx / 40; }
      }
    }

    function say(text) { p.say = text; p.sayT = 1.6; }

    /** swap the sprite sheets between cat and dog, keeping position + state */
    function setSpecies(kind) {
      if (kind === mySpecies) return;
      mySpecies = kind;
      species = kind;
      p.emote = "love"; p.emoteT = 1.1;
      say(SPECIES_CRY[kind]);
      saveState();
    }

    /* ---- commanded tricks ---- */
    function doTrick(kind) {
      p.emote = null; p.restT = 0; p.zoomLeft = 0;
      p.trick = kind; p.trickT = kind === "spin" ? 1.1 : 1.6;
      p.eye = "happy"; p.mouth = "happy"; p.ears = 1;
      say(kind === "speak" ? SPECIES_CRY[mySpecies] : (TRICK_WORDS[kind] || "!"));
      if (kind === "sit") { p.action = "sit"; p.vx = 0; }
      else if (kind === "spin") { p.action = "idle"; p.vx = 0; p.angVel = 14; p.rot = 0; }
      else if (kind === "flip") { startFlip(); p.trickT = 1.2; }
      else if (kind === "speak") { p.action = "idle"; p.vx = 0; p.emote = "bang"; p.emoteT = 0.9; }
      else if (kind === "play") { p.emote = "sleep"; p.emoteT = 4; p.action = "sit"; p.trickT = 4; say("x_x"); }
      else if (kind === "chase") {
        p.zoomLeft = 6; p.targetX = 60 + Math.random() * (window.innerWidth - 120);
        p.trick = null; p.thinkT = 0.4;
      }
    }

    /* ------------------------------------------------------------------ *
     *  right-click menu
     * ------------------------------------------------------------------ */
    var menuEl = null;
    function closeMenu() { if (menuEl) { menuEl.remove(); menuEl = null; } }

    function buildMenu(mx, my) {
      closeMenu();
      var m = document.createElement("div");
      m.style.cssText =
        "position:fixed;z-index:2147483600;min-width:196px;padding:6px;border-radius:12px;" +
        "background:rgba(14,15,20,.97);border:1px solid rgba(120,140,255,.28);" +
        "box-shadow:0 18px 44px rgba(0,0,0,.62);backdrop-filter:blur(8px);" +
        "font:13px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:#dfe3f2;user-select:none;";

      function header(t) {
        var h = document.createElement("div");
        h.textContent = t;
        h.style.cssText = "padding:6px 10px 4px;font-size:10.5px;letter-spacing:.09em;text-transform:uppercase;color:#7d86a8;";
        m.appendChild(h);
      }
      function row(label, glyph, fn) {
        var r = document.createElement("div");
        r.style.cssText = "display:flex;align-items:center;gap:9px;padding:7px 10px;border-radius:8px;cursor:pointer;";
        var g = document.createElement("span"); g.textContent = glyph; g.style.cssText = "width:18px;text-align:center;font-size:15px;";
        var t = document.createElement("span"); t.textContent = label;
        r.appendChild(g); r.appendChild(t);
        r.addEventListener("mouseenter", function () { r.style.background = "rgba(110,135,255,.17)"; });
        r.addEventListener("mouseleave", function () { r.style.background = "transparent"; });
        r.addEventListener("click", function (ev) { ev.stopPropagation(); closeMenu(); fn(); });
        m.appendChild(r);
      }
      function sep() {
        var s = document.createElement("div");
        s.style.cssText = "height:1px;margin:5px 8px;background:rgba(255,255,255,.07);";
        m.appendChild(s);
      }

      /* ---- collapsible subcategory: one compact header row that expands ---- */
      function group(label, glyph, build) {
        var g = document.createElement("div");
        var head = document.createElement("div");
        head.style.cssText =
          "display:flex;align-items:center;gap:9px;padding:7px 10px;border-radius:8px;cursor:pointer;";
        var gi = document.createElement("span");
        gi.textContent = glyph; gi.style.cssText = "width:18px;text-align:center;font-size:15px;";
        var gt = document.createElement("span"); gt.textContent = label; gt.style.cssText = "flex:1;";
        var caret = document.createElement("span");
        caret.textContent = "›";
        caret.style.cssText = "color:#7d86a8;font-size:15px;transition:transform .14s ease;transform-origin:50% 50%;";
        head.appendChild(gi); head.appendChild(gt); head.appendChild(caret);

        var body = document.createElement("div");
        body.style.cssText = "display:none;padding-left:8px;margin-left:8px;border-left:1px solid rgba(255,255,255,.08);";

        head.addEventListener("mouseenter", function () { head.style.background = "rgba(110,135,255,.17)"; });
        head.addEventListener("mouseleave", function () { head.style.background = "transparent"; });
        head.addEventListener("click", function (ev) {
          ev.stopPropagation();
          var open = body.style.display === "block";
          // accordion: only one group open at a time
          openGroups.forEach(function (o) { o.body.style.display = "none"; o.caret.style.transform = "rotate(0deg)"; });
          if (!open) { body.style.display = "block"; caret.style.transform = "rotate(90deg)"; }
          clampMenu();
        });

        openGroups.push({ body: body, caret: caret });

        var prev = m;
        m = body;               // rows built inside build() land in the body
        build();
        m = prev;

        g.appendChild(head); g.appendChild(body);
        m.appendChild(g);
      }

      var openGroups = [];

      header("desk pet");
      group("Species", "🐾", function () {
        row("Cat", "🐱", function () { setSpecies("cat"); });
        row("Dog", "🐶", function () { setSpecies("dog"); });
        row("Dino", "🦖", function () { setSpecies("dino"); });
      });
      group("Tricks", "🎪", function () {
        row("Sit", "🪑", function () { doTrick("sit"); });
        row("Spin", "🌀", function () { doTrick("spin"); });
        row("Backflip", "🤸", function () { doTrick("flip"); });
        row("Speak", "💬", function () { doTrick("speak"); });
        row("Play Dead", "💀", function () { doTrick("play"); });
        row("Zoomies", "💨", function () { doTrick("chase"); });
      });
      group("Feed", "🍽️", function () {
        FOODS.forEach(function (f) {
          row(f.name, f.glyph, function () { spawnItem(f, "food", mx, my - 40); });
        });
      });
      group("Toys", "🧸", function () {
        TOYS.forEach(function (t) {
          row(t.name, t.glyph, function () { spawnItem(t, "toy", mx, my - 40); });
        });
        row("Laser Pointer", "🔦", function () { if (world) { world.laserOn(); say("!!!"); } });
        row("Put Pointer Away", "🚫", function () { if (world) world.laserOff(); });
        row("Put Away Toys", "🧹", function () { clearItem(); });
        row(scrappy ? "Playful Mode: OFF" : "Playful Mode: ON", scrappy ? "😾" : "😺", function () {
          scrappy = !scrappy;
          say(scrappy ? "grrr" : "\u2665");
        });
      });
      sep();
      group("Pets", "👥", function () {
        row("Spawn Another Pet", "➕", function () { spawnPet(mySpecies); });
        row("Spawn a Cat", "🐱", function () { spawnPet("cat"); });
        row("Spawn a Dog", "🐶", function () { spawnPet("dog"); });
        row("Spawn a Dino", "🦖", function () { spawnPet("dino"); });
        row("Remove This Pet", "✖", function () { removePet(self); });
        row("Remove All Pets", "🚫", function () { removeAllPets(); });
      });
      sep();
      group("Home & Events", "🏠", function () {
        row("Everyone Go Home", "🛏️", function () { var h = window.__deskPetHome; if (h) h.sendHome(); });
        row("Snack Rain", "🍗", function () { var h = window.__deskPetHome; if (h) h.fire("snackRain"); });
        row("Toy Storm", "🧸", function () { var h = window.__deskPetHome; if (h) h.fire("toyStorm"); });
        row("Zoomies Hour", "⚡", function () { var h = window.__deskPetHome; if (h) h.fire("zoomies"); });
        row("Release a Butterfly", "🦋", function () { var h = window.__deskPetHome; if (h) h.fire("butterfly"); });
        row("Loose Mouse", "🐁", function () { var h = window.__deskPetHome; if (h) h.fire("mouse"); });
        row("Thunderstorm", "⛈️", function () { var h = window.__deskPetHome; if (h) h.fire("storm"); });
        row("Nap Time", "🌙", function () { var h = window.__deskPetHome; if (h) h.fire("naptime"); });
        row("Throw a Party", "🎉", function () { var h = window.__deskPetHome; if (h) h.fire("party"); });
        row("Shooting Star", "✨", function () { var h = window.__deskPetHome; if (h) h.fire("star"); });
        row("Rainbow", "🌈", function () { var h = window.__deskPetHome; if (h) h.fire("rainbow"); });
        row("Surprise Me", "🎲", function () { var h = window.__deskPetHome; if (h) h.fire(null); });
      });
      sep();
      group("PVP Battle", "⚔️", function () {
        row("Random Rival", "🎲", function () { startBattle(null); });
        row("Fight a Cat", "🐱", function () { startBattle("cat"); });
        row("Fight a Dog", "🐶", function () { startBattle("dog"); });
        row("Fight a Dino", "🦖", function () { startBattle("dino"); });
      });

      document.body.appendChild(m);
      var menuRoot = m;
      function clampMenu() {
        var r = menuRoot.getBoundingClientRect();
        menuRoot.style.left = Math.max(6, Math.min(mx, window.innerWidth - r.width - 6)) + "px";
        menuRoot.style.top = Math.max(6, Math.min(my, window.innerHeight - r.height - 6)) + "px";
      }
      clampMenu();
      menuEl = m;
    }

    /* ---- PVP: pet reacts, then the battle panel opens ---- */
    function startBattle(rival) {
      var api = window.__deskPetBattle;
      if (!api) return;
      p.emote = "bang"; p.emoteT = 1; p.ears = 1;
      say(SPECIES_CRY[mySpecies]);
      api.start(mySpecies, rival, function (result) {
        if (result === "win") { p.emote = "love"; p.emoteT = 2.2; say("winner!"); doTrick("spin"); }
        else { p.emote = "sleep"; p.emoteT = 2.6; say("x_x"); doTrick("play"); }
      });
    }

    function onCtx(e) {
      var r = el.getBoundingClientRect();
      var onPet = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
      if (!onPet && e.target !== itemEl) return;
      e.preventDefault(); e.stopPropagation();
      drag.on = false;
      buildMenu(e.clientX, e.clientY);
    }
    window.addEventListener("contextmenu", onCtx, true);
    window.addEventListener("pointerdown", function (e) {
      if (menuEl && !menuEl.contains(e.target)) closeMenu();
    }, true);

    /* ---- AI: pick idle behaviour while grounded ---- */
    function think(dt) {
      p.thinkT -= dt;
      if (p.pounceT > 0) p.pounceT -= dt;
      if (p.fetchCool > 0) p.fetchCool -= dt;
      var mdx = mouse.x - p.x, mdy = mouse.y - p.y;
      var dist = Math.hypot(mdx, mdy);
      var mouseLive = mouse.has && (performance.now() - mouse.moved) < 2500;
      var near = mouseLive && dist < 300;

      // commanded trick holds everything else off until it expires
      if (p.trick) {
        p.trickT -= dt;
        if (p.trick === "sit" || p.trick === "play") p.action = "sit";
        else p.action = "idle";
        if (p.trickT <= 0) { p.trick = null; p.emote = null; p.angVel = 0; p.thinkT = 0.3; }
        return;
      }

      // HOME + WORLD EVENTS outrank everything: going to bed, hiding from
      // thunder, chasing whatever critter just ran across the floor.
      var homeApi = window.__deskPetHome;
      if (homeApi && homeApi.drive(brainCtx, dt)) return;

      // THE LASER outranks everything — unless this pet is actually hungry
      // and there's food on the floor. Food beats the red dot.
      var foodOut = world ? world.nearestFood(p.x, p.y, p) : null;
      var starving = p.needs && p.needs.energy < 0.7;
      if (world && world.laserActive() && !(foodOut && starving)) {
        var L = world.laserPos();
        var ldx = L.x - p.x, ldy = L.y - p.y;
        var ldist = Math.hypot(ldx, ldy);
        p.act = null; p.restT = 0; p.ears = 1; p.eye = "scared"; p.mouth = "happy";
        p.action = "follow";
        p.targetX = L.x;
        p.speedMul = 2.6;
        p.dir = ldx >= 0 ? 1 : -1;
        if (ldist < 52) {
          // pounce ON it and always come up with nothing
          if (p.pounceT <= 0) {
            p.pounceT = 0.85;
            p.emote = "fight"; p.emoteT = 0.4;
            p.fightWord = FIGHT_WORDS[(Math.random() * FIGHT_WORDS.length) | 0];
            p.sx = 1.3; p.sy = 0.72;
            if (Math.random() < 0.35) say(pick(["got it!", "almost!", "where'd it go", "RAAA"]));
          }
          p.action = "idle";
        } else if (ldy < -70 && Math.abs(ldx) < 110 && p.pounceT <= 0) {
          startHop(L.x); p.pounceT = 0.7;
        }
        return;
      }

      // DOG: carrying a toy back to you
      if (p.carry) {
        if (!world || !world.has(p.carry) || p.carry.heldBy !== p) p.carry = null;
        else {
          var ftx = mouse.has ? mouse.x : window.innerWidth / 2;
          var fdx = ftx - p.x;
          p.action = "follow"; p.targetX = ftx; p.speedMul = 1.5;
          p.dir = fdx >= 0 ? 1 : -1; p.mouth = "happy"; p.eye = "happy"; p.ears = 1;
          if (Math.abs(fdx) < 70) {
            world.release(p.carry, p.dir * 120, -520); p.carry = null;
            say(pick(["fetch!", "again!", "throw it!", "woof!"]));
            p.emote = "love"; p.emoteT = 1; p.action = "sit"; p.thinkT = 1.2; p.fetchCool = 3;
          }
          return;
        }
      }

      // a toy or food anywhere in the SHARED world beats every other urge
      var wItem = (foodOut && starving) ? foodOut : (world ? world.nearest(p.x, p.y, p) : null);
      if (wItem && !world.dragging(wItem)) {
        var idx = wItem.x - p.x, idy = wItem.y - p.y;
        var idist = Math.hypot(idx, idy);
        p.act = null;
        p.restT = 0; p.ears = 1; p.mouth = "happy"; p.eye = "happy";
        if (idist < 46) {
          if (wItem.kind === "food") {
            p.action = "sit"; p.vx *= 0.5;
            p.eatT += dt;
            if (p.eatT > 0.55) {
              p.eatT = 0;
              var r = world.bite(wItem);
              if (r === "last") { say("thanks!"); p.emote = "love"; p.emoteT = 1.6; }
              else if (r === "bite") { say("nom!"); p.emote = "love"; p.emoteT = 0.8; }
            }
          } else {
            // bat the toy away — but only if another pet didn't just hit it
            if (mySpecies === "dog" && !(p.fetchCool > 0) && world.hold(wItem, p)) {
              p.carry = wItem; say(pick(["mine!", "got it!", "*proud*"])); return;
            }
            p.action = "idle";
            var swat = (idx >= 0 ? 1 : -1);
            if (world.swat(wItem, swat)) {
              p.dir = swat; p.emote = "fight";
              p.emoteT = 0.4; p.fightWord = FIGHT_WORDS[(Math.random() * FIGHT_WORDS.length) | 0];
            }
          }
          return;
        }
        // race it down; hop if it's up in the air
        p.action = "follow";
        p.targetX = wItem.x;
        p.speedMul = 1.9;
        p.dir = idx >= 0 ? 1 : -1;
        if (idy < -80 && Math.abs(idx) < 90 && p.pounceT <= 0) { startHop(wItem.x); p.pounceT = 0.7; }
        return;
      }

      // cursor right on top of the pet — mostly friendly, rarely a scrap
      if (mouseLive && dist < 58 && p.emote !== "fight" && p.pounceT <= 0) {
        p.pounceT = 2.4 + Math.random() * 2;
        p.restT = 0;
        p.dir = mdx > 0 ? 1 : -1;
        // feisty pets scrap sometimes; everyone else just enjoys the attention
        var feisty = (p.mood === "grumpy" ? 0.3 : p.mood === "hyper" ? 0.16 : 0.06);
        if (scrappy && Math.random() < feisty) {
          p.emote = "fight"; p.emoteT = 0.55 + Math.random() * 0.35;
          p.fightWord = FIGHT_WORDS[(Math.random() * FIGHT_WORDS.length) | 0];
          p.action = "idle"; p.mouth = "neutral"; p.eye = "scared";
          p.vx += (mdx > 0 ? 1 : -1) * -40;
        } else {
          p.action = "idle"; p.vx *= 0.4;
          p.emote = "love"; p.emoteT = 1.2;
          p.eye = "happy"; p.mouth = "happy"; p.ears = 1;
          p.needs && (p.needs.social = Math.min(1, p.needs.social + 0.3));
          if (Math.random() < 0.5) say(pick(["hi!", "\u2665", "prrr", "hey you", "*leans in*"]));
        }
        return;
      }
      if (p.emote === "fight") { p.action = "idle"; return; } // stay put mid-brawl

      if (near) { // follow the cursor
        p.action = "follow";
        p.targetX = mouse.x;
        p.ears = 1;
        p.mouth = "happy";
        p.restT = 0;
        // cursor is ABOVE the pet -> climb the UI: hop ledge to ledge toward it
        if (mdy < -60 && p.pounceT <= 0) {
          var W = window.__deskPetWorld;
          var step = (W && W.platformToward) ? W.platformToward(p.x, p.y, mouse.x, mouse.y) : null;
          if (step) {
            hopToSpot({ top: step.y, left: step.p.x1, right: step.p.x2 });
            p.pounceT = 0.55;
            if (Math.random() < 0.25) say(pick(["hup!", "climbing!", "parkour", "wait up!"]));
            return;
          }
          if (Math.abs(mdx) < 40) { startHop(mouse.x); p.pounceT = 0.8; return; }
        }
        if (Math.abs(mdx) < 26) { p.eye = mdy < -40 ? "happy" : "open"; }
        else p.eye = "open";
        return;
      }

      // idle long enough with no mouse -> take a nap (Zzz)
      if (p.action === "idle" || p.action === "sit") p.restT += dt; else p.restT = 0;
      if (p.restT > 6 && !p.emote) { p.emote = "sleep"; p.emoteT = 3 + Math.random() * 4; p.eye = "happy"; p.mouth = "neutral"; }
      if (p.emote === "sleep") { p.action = "sit"; if (mouseLive && dist < 260) { p.emote = null; p.restT = 0; } return; }

      // ZOOMIES: mid-fit — dash back and forth like a maniac
      if (p.zoomLeft > 0) {
        p.action = "wander";
        p.eye = "happy"; p.mouth = "happy"; p.ears = 1;
        p.emote = "zoom"; p.emoteT = 0.5;
        if (Math.abs(p.targetX - p.x) < 40 || p.thinkT <= 0) {
          p.zoomLeft--;
          p.targetX = 60 + Math.random() * (window.innerWidth - 120);
          p.thinkT = 0.4 + Math.random() * 0.5;
        }
        return;
      }

      // ---- BRAIN: needs-driven behaviours own the pet when they fire ----
      if (brain && brain.step(brainCtx, dt)) return;
      if (p.thinkT <= 0 && brain && brain.choose(brainCtx)) return;

      if (p.thinkT <= 0) {
        // CAT: sometimes climbs to the highest ledge around for a nap
        if (mySpecies === "cat" && world && world.platforms && Math.random() < 0.12) {
          var pl = world.platforms(), topL = null;
          for (var q = 0; q < pl.length; q++) if (pl[q].y < p.y - 60 && (!topL || pl[q].y < topL.y)) topL = pl[q];
          if (topL) {
            p.napClimb = true; p.thinkT = 6;
            hopToSpot({ top: topL.y, left: topL.x1, right: topL.x2 });
            say(pick(["nap time", "up we go", "*yawn*"]));
            return;
          }
        }
        var roll = Math.random();
        if (roll < 0.24) { p.action = "wander"; p.targetX = 60 + Math.random() * (window.innerWidth - 120); p.thinkT = 2 + Math.random() * 3; }
        else if (roll < 0.42) { p.action = "idle"; p.thinkT = 1.5 + Math.random() * 2.5; }
        else if (roll < 0.55) { startFlip(); p.thinkT = 2 + Math.random() * 2; }
        else if (roll < 0.66) { startHop(p.x + (Math.random() < 0.5 ? -180 : 180) * (0.5 + Math.random())); p.thinkT = 2 + Math.random() * 2; }
        else if (roll < 0.80) { // ZOOMIES fit
          p.zoomLeft = 4 + (Math.random() * 4 | 0);
          p.targetX = 60 + Math.random() * (window.innerWidth - 120);
          p.thinkT = 0.5; p.emote = "zoom"; p.emoteT = 0.7;
        }
        else if (roll < 0.92) { p.action = "idle"; p.thinkT = 2 + Math.random() * 2; }
        else { p.action = "sit"; p.thinkT = 2 + Math.random() * 3; }
        p.mouth = "neutral";
      }
    }
    function startFlip() {
      p.mode = "air"; p.vy = -900; p.vx = p.dir * 120;
      p.angVel = p.dir * 12; p.eye = "happy"; p.mouth = "happy"; p.action = "flip";
    }
    // hop toward targetX, aiming to land on a real page element if one is up there
    function startHop(targetX) {
      targetX = Math.max(HALF, Math.min(window.innerWidth - HALF, targetX));
      var dx = targetX - p.x;
      p.dir = dx >= 0 ? 1 : -1;
      var vy = -980;
      p.perchTop = 0;
      p.mode = "air"; p.vy = vy;
      p.vx = Math.max(-520, Math.min(520, dx * 1.8));
      p.angVel = 0; p.eye = "happy"; p.mouth = "happy"; p.action = "flip";
    }
    // leap up onto a specific spot rect (chat box / session list)
    function hopToSpot(spot) {
      var landX = Math.max(spot.left + 30, Math.min(spot.right - 30, p.x));
      landX = Math.max(HALF, Math.min(window.innerWidth - HALF, landX));
      var dx = landX - p.x;
      p.dir = dx >= 0 ? 1 : -1;
      var rise = p.y - spot.top;
      // overshoot the apex a little so a long climb actually clears the edge
      var vy = -Math.min(2400, Math.sqrt(2 * GRAV * Math.max(140, rise + 90)));
      p.perchTop = spot.top; p.perchL = spot.left; p.perchR = spot.right;
      p.mode = "air"; p.vy = vy;
      p.vx = Math.max(-560, Math.min(560, dx * 1.7));
      p.angVel = 0; p.eye = "happy"; p.mouth = "happy"; p.action = "flip";
    }

    /* ---- physics + integrate ---- */
    var GRAV = 3000, last = performance.now();
    function tick(now) {
      var dt = Math.min(0.033, (now - last) / 1000); last = now;
      var fY = floorY();

      if (p.mode === "drag") {
        p.eye = "happy"; p.mouth = "happy";
        p.rot = Math.max(-0.3, Math.min(0.3, (p.vx || 0) / 4000));
        p.sx = 1.08; p.sy = 0.92;
      } else if (p.mode === "perch") {
        // standing on a real page element — hold position, drop off if it moved/scrolled away
        p.rot += (0 - p.rot) * Math.min(1, dt * 12);
        p.sx += (1 - p.sx) * Math.min(1, dt * 10);
        p.sy += (1 - p.sy) * Math.min(1, dt * 10);
        p.y = p.perchTop;
        think(dt);
        // walk along the ledge toward whatever it's chasing
        if (p.action === "follow" || p.action === "wander") {
          var pdx = p.targetX - p.x;
          if (Math.abs(pdx) > 12) {
            p.dir = pdx > 0 ? 1 : -1;
            p.vx += (p.dir * 150 * speciesSpeed() - p.vx) * Math.min(1, dt * 8);
          } else p.vx *= 0.6;
        } else p.vx *= 0.6;
        p.x += p.vx * dt;
        if (p.x < p.perchL - 20 || p.x > p.perchR + 20 || p.mode === "air") { // walked/hopped off the ledge
          if (p.mode === "perch") { p.mode = "air"; p.vy = -120; }
        }
        p.legPhase += Math.abs(p.vx) * dt * 0.09;
      } else if (p.mode === "air") {
        p.vy += GRAV * dt;
        var prevY = p.y;
        p.x += p.vx * dt; p.y += p.vy * dt;
        p.rot += p.angVel * dt;
        p.vx *= 0.995;
        // walls
        if (p.x < HALF - 40) { p.x = HALF - 40; p.vx = Math.abs(p.vx) * 0.5; p.angVel *= -0.5; }
        if (p.x > window.innerWidth - HALF + 40) { p.x = window.innerWidth - HALF + 40; p.vx = -Math.abs(p.vx) * 0.5; p.angVel *= -0.5; }
        // land on a UI ledge (chat bar, header, card…) on the way down
        var ledge = (p.vy > 0 && window.__deskPetWorld && window.__deskPetWorld.platformUnder)
          ? window.__deskPetWorld.platformUnder(p.x, p.y, p.vy, prevY) : null;
        if (ledge && p.y < fY) {
          p.y = ledge.y;
          p.perchTop = ledge.y; p.perchL = ledge.x1; p.perchR = ledge.x2;
          p.vy = 0; p.vx *= 0.5; p.angVel = 0; p.rot = 0;
          p.mode = "perch"; p.thinkT = 0.3;
          if (p.napClimb) { p.napClimb = false; p.emote = "sleep"; p.emoteT = 10; p.eye = "happy"; p.restT = 7; }
          p.sx = 1.22; p.sy = 0.8;
          p.eye = "happy"; p.mouth = "happy";
          if (Math.random() < 0.3) say(pick(["got it!", "up here!", "\u2665", "nice ledge"]));
        }
        // land
        else if (p.y >= fY) {
          p.perchTop = 0; p.napClimb = false;
          p.y = fY;
          var impact = p.vy;
          if (impact > 350) { // bounce
            p.vy = -impact * 0.45; p.vx *= 0.7; p.angVel *= 0.4;
            p.sx = 1.35; p.sy = 0.65;
          } else { // settle
            p.vy = 0; p.vx *= 0.4; p.angVel = 0;
            p.mode = "ground"; p.thinkT = 0.4;
            p.sx = 1.3; p.sy = 0.7;
            if (impact > 250) { p.eye = "dizzy"; p.mouth = "neutral"; p.dizzyT = 0.9; }
          }
        }
        p.eye = p.eye === "dizzy" ? "dizzy" : (Math.abs(p.vy) > 500 ? "scared" : "open");
      } else { // ground
        think(dt);
        // spinning trick keeps turning; otherwise ease upright
        if (p.trick === "spin") p.rot += p.angVel * dt;
        else if (p.spinV) p.rot += p.spinV * dt;
        else if (p.rotHold) p.rot += (p.rotHold - p.rot) * Math.min(1, dt * 14);
        else p.rot += (0 - p.rot) * Math.min(1, dt * 12);
        var moving = p.action === "wander" || p.action === "follow";
        if (moving) {
          var dx = p.targetX - p.x;
          var speed = (p.zoomLeft > 0 ? 430 : (p.action === "follow" ? 190 : 95)) * (p.speedMul == null ? 1 : p.speedMul) * speciesSpeed();
          if (Math.abs(dx) > 14) {
            var dirWant = dx > 0 ? 1 : -1;
            p.dir = dirWant;
            p.vx += (dirWant * speed - p.vx) * Math.min(1, dt * 8);
          } else { p.vx *= 0.6; if (p.action === "wander") p.action = "idle"; }
        } else p.vx *= 0.6;
        p.x += p.vx * dt;
        // DINO: every heavy step shakes the floor and bounces nearby toys
        if (mySpecies === "dino" && Math.abs(p.vx) > 60) {
          p.stompT = (p.stompT || 0) + dt;
          if (p.stompT > 0.5) {
            p.stompT = 0; p.sx = 1.1; p.sy = 0.88;
            if (world && world.quake) world.quake(p.x, 150);
            if (Math.random() < 0.08) say("STOMP");
          }
        }
        p.x = Math.max(HALF - 40, Math.min(window.innerWidth - HALF + 40, p.x));
        // leg cycle by speed
        p.legPhase += Math.abs(p.vx) * dt * 0.09;
        // breathing squash back to rest
        p.sx += (1 - p.sx) * Math.min(1, dt * 10);
        p.sy += (1 - p.sy) * Math.min(1, dt * 10);
        // dizzy timeout
        if (p.dizzyT > 0) { p.dizzyT -= dt; if (p.dizzyT <= 0) { p.eye = "open"; } }
        else if (p.eye !== "happy" && p.action !== "follow") p.eye = "open";
      }

      // blink (only when eyes plain open)
      p.blinkT -= dt;
      if (p.blinkT <= 0 && p.eye === "open") { p.blinking = 0.12; p.blinkT = 2.5 + Math.random() * 3; }
      if (p.blinking > 0) p.blinking -= dt;
      // emote lifetime (fight cloud / bang / love burst); sleep clears itself in think()
      if (p.emote && p.emote !== "sleep" && p.emoteT > 0) {
        p.emoteT -= dt;
        if (p.emoteT <= 0) { if (p.emote === "fight") p.eye = "dizzy"; p.emote = null; }
      }
      p.tailPhase += dt * 3;
      p.ears += ((p.mode === "drag" || p.action === "follow" ? 1 : 0.6) - p.ears) * Math.min(1, dt * 6);

      if (p.carry) { p.carry.x = p.x + p.dir * 34; p.carry.y = p.y - 26; }
      stepItem(dt);
      if (p.sayT > 0) p.sayT -= dt; else p.say = null;

      render();
      raf = requestAnimationFrame(tick);
    }

    /* ---- draw ---- */
    function render() {
      ctx.clearRect(0, 0, SIZE, SIZE);
      ctx.imageSmoothingEnabled = false;

      var spd = Math.abs(p.vx);

      // pick animation state + its sheet geometry (per species)
      var dog = mySpecies === "dog" ? window.__deskPetDog
              : mySpecies === "dino" ? window.__deskPetDino : null;
      var sheet, fw, fh, FRAMES;
      var state = (p.mode === "air" || p.mode === "drag") ? "jump"
                : spd > 150 ? "run"
                : spd > 6 ? "walk" : "idle";
      if (dog && dog[state]) {
        var d = dog[state];
        sheet = d.img; fw = d.fw; fh = d.fh; FRAMES = d.n;
      } else if (state === "jump") {
        sheet = jumpImg; fw = 78; fh = 96; FRAMES = 8;
      } else if (state === "run") {
        sheet = runImg;  fw = 68; fh = 96; FRAMES = 8;
      } else if (state === "walk") {
        sheet = walkImg; fw = 64; fh = 96; FRAMES = 10;
      } else {
        sheet = idleImg; fw = 64; fh = 96; FRAMES = 10;
      }

      // frame selection
      var frame;
      if (p.mode === "air" || p.mode === "drag") {
        // map vertical velocity across the jump arc: rising -> early, falling -> late
        var t = Math.max(0, Math.min(1, (p.vy + 900) / 1800));
        frame = Math.min(FRAMES - 1, Math.floor(t * FRAMES));
      } else if (spd > 6) {
        frame = Math.floor(p.legPhase / (Math.PI / 3)) % FRAMES;
        if (frame < 0) frame += FRAMES;
      } else {
        // gentle idle breathing cycle off the tail phase
        frame = Math.floor(p.tailPhase / (Math.PI / 3)) % FRAMES;
        if (frame < 0) frame += FRAMES;
      }

      // zoomies dust FIRST so it sits BEHIND the pet (canvas already body-mirrored,
      // so +1 points at the tail automatically)
      if (p.emote === "zoom") {
        drawZoom(ctx, HALF, HALF + 8, performance.now() / 1000, 1);
      }

      // sprite not decoded yet? fall back to the vector creature so it's never blank
      if (!sheet.complete || !sheet.naturalWidth) {
        var eye = p.blinking > 0 ? "blink" : p.eye;
        drawCreature(ctx, HALF, HALF - 6, {
          legPhase: p.legPhase, breathe: 0, ears: p.ears,
          eye: eye, mouth: p.mouth, tailPhase: p.tailPhase,
          airborne: p.mode === "air" ? 1 : 0,
        });
      } else {
        var scale = 0.92;                            // 96px art -> ~88px on the 96 canvas
        var dw = fw * scale, dh = fh * scale;
        ctx.drawImage(sheet, frame * fw, 0, fw, fh,
          HALF - dw / 2, HALF - dh / 2 - 2, dw, dh);
      }

      // ---- comic-strip emote overlays (counter-flip so text isn't mirrored) ----
      if (p.emote && p.emote !== "zoom") {
        var et = performance.now() / 1000;
        ctx.save();
        if (p.dir < 0) { ctx.translate(SIZE, 0); ctx.scale(-1, 1); } // undo body mirror
        if (p.emote === "fight") drawFightCloud(ctx, HALF, HALF - 6, et, p.fightWord);
        else if (p.emote === "sleep") drawZzz(ctx, HALF + 24, HALF - 26, et);
        else if (p.emote === "love") { drawHeart(ctx, HALF - 16, HALF - 30, et); drawHeart(ctx, HALF + 14, HALF - 36, et + 1); }
        else if (p.emote === "bang") drawBang(ctx, HALF + 22, HALF - 28);
        ctx.restore();
      }

      // speech bubble (counter-flipped so the text reads normally)
      if (p.say) {
        ctx.save();
        if (p.dir < 0) { ctx.translate(SIZE, 0); ctx.scale(-1, 1); }
        ctx.font = "bold 12px system-ui,sans-serif";
        var tw = ctx.measureText(p.say).width;
        var bw = tw + 16, bh = 20, bx = HALF - bw / 2, by = 4;
        ctx.globalAlpha = Math.min(1, p.sayT * 2.2);
        ctx.fillStyle = "#fff";
        roundRect(ctx, bx, by, bw, bh, 9); ctx.fill();
        ctx.beginPath();
        ctx.moveTo(HALF - 5, by + bh - 1); ctx.lineTo(HALF + 4, by + bh - 1); ctx.lineTo(HALF, by + bh + 7);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#14151a";
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText(p.say, HALF, by + bh / 2 + 1);
        ctx.globalAlpha = 1;
        ctx.restore();
      }

      if (item) {
        itemEl.style.transform =
          "translate3d(" + (item.x - 20).toFixed(1) + "px," + (item.y - 20).toFixed(1) + "px,0) rotate(" + item.rot.toFixed(2) + "rad)";
      }

      var tx = p.x - HALF, ty = p.y - HALF;
      el.style.transform =
        "translate3d(" + tx.toFixed(1) + "px," + ty.toFixed(1) + "px,0) rotate(" + p.rot.toFixed(3) + "rad) scale(" + (p.sx * p.dir).toFixed(3) + "," + p.sy.toFixed(3) + ")";

      // shadow follows x, sits on floor, shrinks with height
      var h = Math.max(0, floorY() - p.y);
      var sc = Math.max(0.35, 1 - h / 700);
      shadow.style.transform = "translate3d(" + (p.x - 35) + "px," + (floorY() + FEET - 14) + "px,0) scaleX(" + sc.toFixed(2) + ")";
      shadow.style.opacity = (0.35 * sc).toFixed(2);
    }

    var raf = requestAnimationFrame(tick);

    var self = {
      get species() { return mySpecies; },
      destroy: function () {
        if (brain) brain.unregister(brainCtx);
        if (p.carry && world) { world.release(p.carry, 0, 0); p.carry = null; }
        cancelAnimationFrame(raf);
        el.removeEventListener("pointerdown", onDown);
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
        window.removeEventListener("contextmenu", onCtx, true);
        window.removeEventListener("pointermove", onItemMove);
        window.removeEventListener("pointerup", onItemUp);
        closeMenu();
        el.remove(); shadow.remove(); itemEl.remove();
      },
    };
    return self;
  }

  /* ------------------------------------------------------------------ *
   *  header toggle + persistence + teardown
   * ------------------------------------------------------------------ */
  var store = PallariumModules.store(MOD);
  var btnRef = null;
  var pets = [];
  var MAX_PETS = 8;

  function saveState() {
    store.set({
      on: pets.length > 0,
      species: species,
      pets: pets.map(function (pt) { return pt.species; }).slice(0, MAX_PETS),
    });
    if (btnRef) btnRef.style.opacity = pets.length ? "1" : "0.5";
    // the house belongs to the pets: no pets, no house, no events
    var h = window.__deskPetHome;
    if (h) { if (pets.length) h.show(); else h.hide(); }
  }
  window.__deskPetSave = saveState;

  function spawnPet(kind) {
    if (pets.length >= MAX_PETS) return null;
    var pt = makePet({ species: kind || species });
    pets.push(pt);
    controller = pets[0];
    saveState();
    return pt;
  }
  window.__deskPetSpawn = spawnPet;

  function removePet(pt) {
    var i = pets.indexOf(pt);
    if (i < 0) return;
    pets.splice(i, 1);
    pt.destroy();
    controller = pets[0] || null;
    if (!pets.length) clearWorld();
    saveState();
  }
  window.__deskPetRemove = removePet;

  /** last pet gone = nothing left to play with, so sweep the floor */
  function clearWorld() {
    var w = window.__deskPetWorld;
    if (w) { try { w.clearAll(); } catch (e) {} }
  }

  function removeAllPets() {
    pets.forEach(function (pt) { pt.destroy(); });
    pets = [];
    controller = null;
    clearWorld();
    saveState();
  }
  window.__deskPetRemoveAll = removeAllPets;

  function setPet(on) {
    if (on && !pets.length) spawnPet(species);
    else if (!on) removeAllPets();
    saveState();
  }

  PallariumModules.addHeaderButton(MOD, "🐾", "Desk Pet — toggle your screen buddy", function () {
    setPet(!pets.length);
  });
  // grab the button element to reflect state (best-effort)
  setTimeout(function () { btnRef = document.querySelector('[data-mod-btn="' + MOD + '"]') || null; }, 0);

  store.get().then(function (d) {
    if (d && SPECIES_CRY[d.species]) species = d.species;
    if (d && d.pets && d.pets.length) {
      d.pets.slice(0, MAX_PETS).forEach(function (s) { spawnPet(SPECIES_CRY[s] ? s : species); });
    } else if (d && d.on) setPet(true);
  }).catch(function () {});

  PallariumModules.onTeardown(MOD, function () {
    removeAllPets();
    var h = window.__deskPetHome;
    if (h) { try { h.__kill(); } catch (e) {} }
    var w = window.__deskPetWorld;
    if (w) { try { w.__kill(); } catch (e) {} }
  });
})();
